// Bounded geometry descriptions: no executable code or remote asset URLs.
const number=(min,max)=>({type:'number',minimum:min,maximum:max});
const color={type:'string',pattern:'^#[0-9a-fA-F]{6}$'};
export const creationSchemas={
 outfit:{type:'object',additionalProperties:false,properties:{kind:{type:'string',enum:['skirt']},name:{type:'string',minLength:1,maxLength:40},length:number(.18,.29),flare:number(.035,.105),pleats:{type:'integer',minimum:8,maximum:24},checkSize:number(.025,.10),color,accent:color},required:['kind','name','length','flare','pleats','checkSize','color','accent']},
 home:{type:'object',additionalProperties:false,properties:{kind:{type:'string',enum:['sofa']},name:{type:'string',minLength:1,maxLength:40},width:number(1.65,2.05),depth:number(.78,.90),backHeight:number(.72,.95),armWidth:number(.10,.19),cushions:{type:'integer',minimum:2,maximum:3},color,accent:color,placement:{type:'string',enum:['window']}},required:['kind','name','width','depth','backHeight','armWidth','cushions','color','accent','placement']}
};
export function validateCreation(scope,value){if(value===null||value===undefined)return null;const s=creationSchemas[scope];if(!s||typeof value!=='object'||Array.isArray(value)||Object.keys(value).length!==s.required.length)throw Error('作品结构不完整');for(const [k,r]of Object.entries(s.properties)){const v=value[k];if(r.type==='number'||r.type==='integer'){if(!Number.isFinite(v)||v<r.minimum||v>r.maximum||r.type==='integer'&&!Number.isInteger(v))throw Error('作品尺寸超出安全范围')}else if(typeof v!=='string'||r.enum&&!r.enum.includes(v)||r.pattern&&!new RegExp(r.pattern).test(v)||r.maxLength&&(v.trim().length<r.minLength||v.length>r.maxLength))throw Error('作品参数不正确')}return structuredClone(value)}
export const creationExamples={outfit:{kind:'skirt',name:'林间格子裙',length:.24,flare:.075,pleats:16,checkSize:.055,color:'#718a73',accent:'#eee6ce'},home:{kind:'sofa',name:'奶油云朵沙发',width:1.95,depth:.86,backHeight:.87,armWidth:.15,cushions:2,color:'#e8dfca',accent:'#a3b09a',placement:'window'}};
